     1	import Foundation
     2	
     3	/// The live loudness meter (road map "audio" AP7, spec §11 AU-70…AU-74):
     4	/// momentary, short-term and integrated LUFS and the true-peak maximum of
     5	/// the TRUE mix, rebuilt on the main thread from what each tap copied into
     6	/// its sink's `MixRing`.
     7	///
     8	/// **The sum is by frame, not by arrival.** Each tap is called on one
     9	/// thread in a cycle, but the tracks' buffers in one cycle start up to
    10	/// 13 ms apart (spike S3), so the consumer adds each track's samples at
    11	/// their own frame, times the plan's envelope there (`MediaPeaks.envelope`,
    12	/// the level meter's multiply), a mono track in both channels. Frame f is
    13	/// summed once every track has delivered past it, except a track not
    14	/// sounding at f (outside its own spans: a gap, or past its last clip, where
    15	/// the tap delivers nothing, #65) or `stallLag` behind the leading track;
    16	/// such a track is silence at f.
    17	///
    18	/// **Continuity** (AU-72). A chunk that continues its own track's stream is
    19	/// summed; one that MOVES its track is asked the reset rule once the chunks
    20	/// before it are summed: more than `behindTolerance` behind the frame the
    21	/// sum reached, or more than `aheadTolerance` past it with a track sounding
    22	/// in between, is a `jump` and the measurement starts again from it; inside
    23	/// the tolerances, frames before the reached frame are dropped, so pause and
    24	/// continue and an edit's rebuild neither reset nor count a frame twice.
    25	/// After a seek the player hands each track a buffer or two of the OLD
    26	/// position first, not in step across tracks (measured, AP7), which is why
    27	/// a track that has not moved yet drops its old stream until it does
    28	/// (`LiveLoudness+Sum.swift`'s `admit`).
    29	///
    30	/// The lane and the sum are `LiveLoudness+Sum.swift`, under the 400-line rule.
    31	///
    32	/// MAIN THREAD ONLY: `Playback`'s meter timer is its one caller, so, like
    33	/// `LevelMeter`, it holds no lock.
    34	struct LiveLoudnessReading: Equatable {
    35	    var momentaryLUFS: Double?
    36	    var shortTermLUFS: Double?
    37	    var integratedLUFS: Double?
    38	    var truePeakDBTP: Double?
    39	    /// Summing frames at ×1 now (within `LiveLoudness.liveWindow`).
    40	    var measuring: Bool
    41	    /// The first frame measured since the reset, and the frame the sum reached.
    42	    var fromFrame: Int64?
    43	    var toFrame: Int64?
    44	    var sampleRate: Int?
    45	    var resets: Int
    46	    var lastReset: LiveLoudness.ResetReason?
    47	    /// Playing at a rate other than ×1: nothing is measured (the footer says so).
    48	    var offSpeed = false
    49	    /// The build runs track compressors or limiters, which the preview runs
    50	    /// per composition track (spec §11 AU-153): the footer says approximate.
    51	    var tracksApproximate = false
    52	
    53	    static let empty = LiveLoudnessReading(
    54	        momentaryLUFS: nil, shortTermLUFS: nil, integratedLUFS: nil, truePeakDBTP: nil,
    55	        measuring: false, fromFrame: nil, toFrame: nil, sampleRate: nil, resets: 0,
    56	        lastReset: nil)
    57	}
    58	
    59	final class LiveLoudness {
    60	    enum ResetReason: String { case manual, jump, overrun }
    61	
    62	    /// Seconds of frames (AU-72, AU-70).
    63	    static let aheadTolerance = 0.1, behindTolerance = 1.0, stallLag = 0.5
    64	    /// How recently the sum must have moved for the reading to be live (AU-74).
    65	    static let liveWindow: TimeInterval = 0.15
    66	
    67	    private(set) var reading = LiveLoudnessReading.empty
    68	    /// The mix's last 100 ms per channel: sample peak and RMS. Nil unless
    69	    /// measuring.
    70	    private(set) var bars: LevelMeterReading?
    71	    /// Called when `reading` changes.
    72	    var onReading: ((LiveLoudnessReading) -> Void)?
    73	    /// Frames fed to the meter since the last reset (what a proof counts).
    74	    var fedFrames: Int64 = 0
    75	
    76	    // The sum's state is internal only so `LiveLoudness+Sum.swift` can write
    77	    // it; nothing else does.
    78	    var lanes: [ObjectIdentifier: LiveLoudnessLane] = [:]
    79	    var order: [ObjectIdentifier] = []
    80	    var meter: LoudnessMeter?
    81	    /// The taps' rate the measurement is at.
    82	    var rate: Int?
    83	    /// The next frame the sum adds; nil before the first one after a reset.
    84	    var reached: Int64?
    85	    /// The first frame summed since the reset.
    86	    var measuredFrom: Int64?
    87	    var lastAdvance: TimeInterval?
    88	    private var barLeft: [Float] = []
    89	    private var barRight: [Float] = []
    90	    private var barNext = 0
    91	    private var barCount = 0
    92	
    93	    init() {}
    94	
    95	    // MARK: - The tick
    96	
    97	    /// The meter timer's tick: drains every track's ring and sums what it can.
    98	    func consume(
    99	        _ meters: [LevelMeterTrack], rate playRate: Float, now: TimeInterval,
   100	        tracksApproximate: Bool = false
   101	    ) {
   102	        if reading.tracksApproximate != tracksApproximate {
   103	            var next = reading
   104	            next.tracksApproximate = tracksApproximate
   105	            commit(next)
   106	        }
   107	        syncLanes(meters)
   108	        var overran = false
   109	        var drained: [(lane: LiveLoudnessLane, chunks: [MixChunk])] = []
   110	        for id in order {
   111	            guard let lane = lanes[id] else { continue }
   112	            let got = lane.track.sink.ring.drain()
   113	            overran = overran || got.overran
   114	            drained.append((lane, got.chunks))
   115	        }
   116	        if playRate == 0 {
   117	            stop()
   118	            return
   119	        }
   120	        // AU-72: measured only at ×1; at any other rate the chunks are discarded.
   121	        guard playRate == 1 else {
   122	            for item in drained { item.lane.stream = item.chunks.last?.end ?? item.lane.stream }
   123	            dropPending()
   124	            bars = nil
   125	            lastAdvance = nil
   126	            var next = reading
   127	            next.momentaryLUFS = nil
   128	            next.shortTermLUFS = nil
   129	            next.measuring = false
   130	            next.offSpeed = true
   131	            commit(next)
   132	            return
   133	        }
   134	        if overran { reset(.overrun) }
   135	        let rates = Set(drained.flatMap { $0.chunks.map(\.sampleRate) })
   136	        if rates.count == 1, let taps = rates.first, taps != rate {
   137	            rate = taps
   138	            if measuredFrom != nil {
   139	                reset(.jump)
   140	            } else {
   141	                meter = LoudnessMeter(sampleRate: Double(taps), channelCount: 2)
   142	            }
   143	        }
   144	        if rates.count <= 1, let sampleRate = rate, meter != nil {
   145	            admit(drained, rate: sampleRate, now: now)
   146	        }
   147	        let live = lastAdvance.map { now - $0 <= Self.liveWindow } ?? false
   148	        bars = live ? mixBars() : nil
   149	        refresh(measuring: live)
   150	    }
   151	
   152	    /// Clears the measurement; the next chunk starts a new one.
   153	    func reset(_ reason: ResetReason) {
   154	        meter = rate.flatMap { LoudnessMeter(sampleRate: Double($0), channelCount: 2) }
   155	        for lane in lanes.values {
   156	            lane.pending = []
   157	            lane.end = nil
   158	            lane.awaiting = nil
   159	            if reason == .overrun { lane.stream = nil }
   160	        }
   161	        reached = nil
   162	        measuredFrom = nil
   163	        fedFrames = 0
   164	        barNext = 0
   165	        barCount = 0
   166	        var next = reading
   167	        next.momentaryLUFS = nil
   168	        next.shortTermLUFS = nil
   169	        next.integratedLUFS = nil
   170	        next.truePeakDBTP = nil
   171	        next.fromFrame = nil
   172	        next.toFrame = nil
   173	        next.resets += 1
   174	        next.lastReset = reason
   175	        commit(next)
   176	    }
   177	
   178	    /// Rate 0: what the rings still hold was rendered ahead and never heard,
   179	    /// so it is dropped; frames already summed stay measured, though the
   180	    /// player renders ahead of the playhead (AU-72). M, S, I and TP hold
   181	    /// their last ×1 values.
   182	    func stop() {
   183	        for lane in lanes.values {
   184	            lane.stream = lane.track.sink.ring.drain().chunks.last?.end ?? lane.stream
   185	        }
   186	        dropPending()
   187	        bars = nil
   188	        lastAdvance = nil
   189	        var next = reading
   190	        next.momentaryLUFS = meter?.momentaryLUFS
   191	        next.shortTermLUFS = meter?.shortTermLUFS
   192	        next.measuring = false
   193	        next.offSpeed = false
   194	        commit(next)
   195	    }
   196	
   197	    // MARK: - The sum
   198	
   199	    private func syncLanes(_ meters: [LevelMeterTrack]) {
   200	        let ids = meters.map { ObjectIdentifier($0.sink) }
   201	        guard ids != order else { return }
   202	        var next: [ObjectIdentifier: LiveLoudnessLane] = [:]
   203	        for meter in meters {
   204	            let id = ObjectIdentifier(meter.sink)
   205	            next[id] = lanes[id] ?? LiveLoudnessLane(meter)
   206	        }
   207	        lanes = next
   208	        order = ids
   209	    }
   210	
   211	    var allLanes: [LiveLoudnessLane] { order.compactMap { lanes[$0] } }
   212	
   213	    private func dropPending() {
   214	        for lane in lanes.values {
   215	            lane.pending = []
   216	            if let end = lane.end, let reached { lane.end = min(end, reached) }
   217	        }
   218	    }
   219	
   220	    // MARK: - The bars and the reading
   221	
   222	    func pushBars(_ left: [Float], _ right: [Float], rate: Int) {
   223	        let size = max(1, rate / 10)
   224	        if barLeft.count != size {
   225	            barLeft = [Float](repeating: 0, count: size)
   226	            barRight = barLeft
   227	            barNext = 0
   228	            barCount = 0
   229	        }
   230	        for i in left.indices {
   231	            barLeft[barNext] = left[i]
   232	            barRight[barNext] = right[i]
   233	            barNext = (barNext + 1) % size
   234	        }
   235	        barCount = min(size, barCount + left.count)
   236	    }
   237	
   238	    /// Sample peak and RMS per channel of the mix's last 100 ms.
   239	    private func mixBars() -> LevelMeterReading? {
   240	        guard barCount > 0 else { return nil }
   241	        var peak: (Float, Float) = (0, 0)
   242	        var power: (Float, Float) = (0, 0)
   243	        for k in 0..<barCount {
   244	            let i = (barNext - 1 - k + barLeft.count) % barLeft.count
   245	            peak = (max(peak.0, abs(barLeft[i])), max(peak.1, abs(barRight[i])))
   246	            power = (power.0 + barLeft[i] * barLeft[i], power.1 + barRight[i] * barRight[i])
   247	        }
   248	        let n = Float(barCount)
   249	        return LevelMeterReading(
   250	            peakLeft: peak.0, peakRight: peak.1, rmsLeft: (power.0 / n).squareRoot(),
   251	            rmsRight: (power.1 / n).squareRoot())
   252	    }
   253	
   254	    private func refresh(measuring: Bool) {
   255	        var next = reading
   256	        next.measuring = measuring
   257	        next.offSpeed = false
   258	        next.sampleRate = rate
   259	        next.fromFrame = measuredFrom
   260	        next.toFrame = measuredFrom == nil ? nil : reached
   261	        if let meter, fedFrames > 0 {
   262	            let report = meter.finish()
   263	            next.momentaryLUFS = meter.momentaryLUFS
   264	            next.shortTermLUFS = meter.shortTermLUFS
   265	            next.integratedLUFS = report.integratedLUFS
   266	            next.truePeakDBTP = report.truePeakDBTP
   267	        }
   268	        commit(next)
   269	    }
   270	
   271	    private func commit(_ next: LiveLoudnessReading) {
   272	        guard next != reading else { return }
   273	        reading = next
   274	        onReading?(next)
   275	    }
   276	}
     1	import Foundation
     2	
     3	/// One composition track: its chunks not yet summed and how far it has
     4	/// delivered since the reset.
     5	final class LiveLoudnessLane {
     6	    let track: LevelMeterTrack
     7	    var pending: [MixChunk] = []
     8	    var end: Int64?
     9	    /// Where its last chunk ended, whether summed or not; kept across a
    10	    /// reset (but an overrun's), so a chunk that continues it is not a move.
    11	    var stream: Int64?
    12	    /// Frames dropped while awaiting its move; nil when not awaiting.
    13	    var awaiting: Int64?
    14	    private var spanRate = 0
    15	    private var spanFrames: [Range<Int64>] = []
    16	
    17	    init(_ track: LevelMeterTrack) { self.track = track }
    18	
    19	    /// Its `sounding` spans on the frame grid: f is in one when f's tick
    20	    /// (`f·600000/rate`, rounded down) is.
    21	    func spans(rate: Int) -> [Range<Int64>] {
    22	        if rate != spanRate {
    23	            spanRate = rate
    24	            spanFrames = track.sounding.map { LiveLoudness.frames($0, rate: rate) }
    25	        }
    26	        return spanFrames
    27	    }
    28	
    29	    /// The first frame at or after `f` this track sounds at, or nil.
    30	    func firstSounding(from f: Int64, rate: Int) -> Int64? {
    31	        spans(rate: rate).filter { $0.upperBound > f }.map { max($0.lowerBound, f) }.min()
    32	    }
    33	
    34	    func sounds(in range: Range<Int64>, rate: Int) -> Bool {
    35	        !range.isEmpty && spans(rate: rate).contains { $0.overlaps(range) }
    36	    }
    37	}
    38	
    39	/// `LiveLoudness`'s sum (road map "audio" AP7, spec §11 AU-70, AU-72): what a
    40	/// drained chunk does to the measurement, and the frame-by-frame sum. Its own
    41	/// file under the 400-line rule; the state it reads is `LiveLoudness`'s.
    42	extension LiveLoudness {
    43	    /// [⌈a·rate/600000⌉, ⌈b·rate/600000⌉): the frames whose ticks fall in `span`.
    44	    static func frames(_ span: Range<Ticks>, rate: Int) -> Range<Int64> {
    45	        func up(_ t: Ticks) -> Int64 {
    46	            let n = t * Int64(rate)
    47	            return n >= 0 ? (n + ReelTime.perSecond - 1) / ReelTime.perSecond : n / ReelTime.perSecond
    48	        }
    49	        let low = up(span.lowerBound)
    50	        return low..<max(low, up(span.upperBound))
    51	    }
    52	
    53	    /// A chunk MOVES its track when it continues neither the track's own
    54	    /// stream (what it delivered last, kept across resets) nor what it
    55	    /// delivered to the measurement; a new track's first chunk moves only
    56	    /// while a measurement is running. With no move, every chunk is summed.
    57	    /// Otherwise the chunks before each track's first move are summed, then
    58	    /// the moves are asked the reset rule. On a jump, or on a move with no
    59	    /// measurement running, each track keeps what follows its own last move
    60	    /// (the new position) and a track with none is AWAITING: the player
    61	    /// hands each track a buffer or two of the old position after a seek or
    62	    /// a play from elsewhere, so what continues its old stream is dropped
    63	    /// until it moves, for at most `stallLag` of frames.
    64	    func admit(_ drained: [(lane: LiveLoudnessLane, chunks: [MixChunk])], rate: Int, now: TimeInterval) {
    65	        var items: [(lane: LiveLoudnessLane, chunks: [MixChunk], first: Int?, last: Int?)] = []
    66	        for (lane, all) in drained where !all.isEmpty {
    67	            var chunks: [MixChunk] = []
    68	            var first: Int?
    69	            var last: Int?
    70	            var end = lane.end
    71	            for chunk in all {
    72	                let moved = lane.stream.map {
    73	                    !continues(chunk.start, after: $0, rate: rate)
    74	                        || end.map { !continues(chunk.start, after: $0, rate: rate) } ?? false
    75	                } ?? (reached != nil)
    76	                lane.stream = chunk.end
    77	                end = chunk.end
    78	                if let dropped = lane.awaiting {
    79	                    if !moved, dropped < Self.frames(Self.stallLag, rate) {
    80	                        lane.awaiting = dropped + Int64(chunk.frames)
    81	                        continue
    82	                    }
    83	                    lane.awaiting = nil
    84	                }
    85	                if moved {
    86	                    first = first ?? chunks.count
    87	                    last = chunks.count
    88	                }
    89	                chunks.append(chunk)
    90	            }
    91	            items.append((lane, chunks, first, last))
    92	        }
    93	        let moves = items.filter { $0.first != nil }
    94	        guard !moves.isEmpty else {
    95	            for item in items {
    96	                for chunk in item.chunks { enqueue(chunk, to: item.lane, rate: rate) }
    97	            }
    98	            advance(rate: rate, now: now)
    99	            return
   100	        }
   101	        let fresh = reached == nil
   102	        if !fresh {
   103	            for item in items {
   104	                for chunk in item.chunks[..<(item.first ?? item.chunks.count)] {
   105	                    enqueue(chunk, to: item.lane, rate: rate)
   106	                }
   107	            }
   108	            advance(rate: rate, now: now)
   109	        }
   110	        if fresh || moves.contains(where: { isJump($0.chunks[$0.first ?? 0].start, rate: rate) }) {
   111	            if !fresh { reset(.jump) }
   112	            let moved = Set(moves.map { ObjectIdentifier($0.lane) })
   113	            for lane in allLanes where !moved.contains(ObjectIdentifier(lane)) {
   114	                lane.awaiting = 0
   115	            }
   116	            for item in moves {
   117	                for chunk in item.chunks[(item.last ?? 0)...] {
   118	                    enqueue(chunk, to: item.lane, rate: rate)
   119	                }
   120	            }
   121	        } else {
   122	            for item in moves {
   123	                for chunk in item.chunks[(item.first ?? 0)...] {
   124	                    enqueue(chunk, to: item.lane, rate: rate)
   125	                }
   126	            }
   127	        }
   128	        advance(rate: rate, now: now)
   129	    }
   130	
   131	    func continues(_ start: Int64, after end: Int64, rate: Int) -> Bool {
   132	        start >= end - Self.frames(Self.behindTolerance, rate)
   133	            && start <= end + Self.frames(Self.aheadTolerance, rate)
   134	    }
   135	
   136	    /// AU-72's rule against the frame the sum reached.
   137	    func isJump(_ start: Int64, rate: Int) -> Bool {
   138	        guard let at = reached else { return false }
   139	        if start < at - Self.frames(Self.behindTolerance, rate) { return true }
   140	        guard start > at + Self.frames(Self.aheadTolerance, rate) else { return false }
   141	        return allLanes.contains { $0.sounds(in: at..<start, rate: rate) }
   142	    }
   143	
   144	    static func frames(_ seconds: Double, _ rate: Int) -> Int64 {
   145	        Int64((seconds * Double(rate)).rounded())
   146	    }
   147	
   148	    func enqueue(_ chunk: MixChunk, to lane: LiveLoudnessLane, rate: Int) {
   149	        var chunk = chunk
   150	        if let end = lane.end, chunk.start < end {
   151	            if chunk.start + Int64(rate / 100) < end {
   152	                // A restart behind its own delivery: what was pending was
   153	                // rendered for a position the player left.
   154	                lane.pending = []
   155	                lane.end = nil
   156	            } else {
   157	                chunk = Self.dropping(chunk, before: end)
   158	            }
   159	        }
   160	        lane.end = max(lane.end ?? chunk.end, chunk.end)
   161	        guard chunk.frames > 0 else { return }
   162	        if let reached {
   163	            // Frames the sum already passed are not summed again.
   164	            guard chunk.end > reached else { return }
   165	        }
   166	        lane.pending.append(chunk)
   167	    }
   168	
   169	    static func dropping(_ chunk: MixChunk, before frame: Int64) -> MixChunk {
   170	        let skip = Int(min(max(0, frame - chunk.start), Int64(chunk.frames)))
   171	        return MixChunk(
   172	            start: chunk.start + Int64(skip), frames: chunk.frames - skip,
   173	            channels: chunk.channels, sampleRate: chunk.sampleRate,
   174	            left: Array(chunk.left[skip...]),
   175	            right: chunk.channels == 2 ? Array(chunk.right[skip...]) : [])
   176	    }
   177	
   178	    /// Sums every frame every waited-on track has delivered past.
   179	    func advance(rate: Int, now: TimeInterval) {
   180	        let all = allLanes
   181	        if reached == nil {
   182	            guard let first = all.flatMap(\.pending).map(\.start).min() else { return }
   183	            reached = first
   184	        }
   185	        guard let at = reached, let meter else { return }
   186	        let leading = all.compactMap(\.end).max() ?? at
   187	        var limit = leading
   188	        for lane in all {
   189	            let delivered = lane.end ?? at
   190	            // The first frame it sounds at and has not delivered: none, and
   191	            // it is not waited on.
   192	            guard let owed = lane.firstSounding(from: delivered, rate: rate) else { continue }
   193	            // A stalled track is silence, not waited on.
   194	            if owed < leading - Self.frames(Self.stallLag, rate) { continue }
   195	            if let wait = lane.firstSounding(from: max(delivered, at), rate: rate) {
   196	                limit = min(limit, wait)
   197	            }
   198	        }
   199	        guard limit > at else { return }
   200	        let count = Int(limit - at)
   201	        var left = [Float](repeating: 0, count: count)
   202	        var right = [Float](repeating: 0, count: count)
   203	        for lane in all {
   204	            let ramps = lane.track.ramps
   205	            for chunk in lane.pending where chunk.end > at && chunk.start < limit {
   206	                let origin = chunk.start
   207	                for f in max(origin, at)..<min(origin + Int64(chunk.frames), limit) {
   208	                    let gain = Float(MediaPeaks.envelope(ramps, at: f * ReelTime.perSecond / Int64(rate)))
   209	                    let i = Int(f - origin)
   210	                    let o = Int(f - at)
   211	                    let x = chunk.left[i] * gain
   212	                    left[o] += x
   213	                    right[o] += chunk.channels == 2 ? chunk.right[i] * gain : x
   214	                }
   215	            }
   216	            lane.pending.removeAll { $0.end <= limit }
   217	        }
   218	        var interleaved = [Float](repeating: 0, count: count * 2)
   219	        for i in 0..<count {
   220	            interleaved[2 * i] = left[i]
   221	            interleaved[2 * i + 1] = right[i]
   222	        }
   223	        interleaved.withUnsafeBufferPointer { meter.feed($0.baseAddress!, frames: count) }
   224	        pushBars(left, right, rate: rate)
   225	        if measuredFrom == nil { measuredFrom = at }
   226	        fedFrames += Int64(count)
   227	        reached = limit
   228	        lastAdvance = now
   229	    }
   230	}
