        q = 0.5003270373238773
        k = tan(Double.pi * f0 / sampleRate)
        let d = 1.0 + k / q + k * k
        let highPass = LoudnessMeter.Biquad(
            b0: 1, b1: -2, b2: 1, a1: 2.0 * (k * k - 1.0) / d, a2: (1.0 - k / q + k * k) / d)
